<?php
require_once __DIR__.'/config.php';
if (!is_admin()) { flash('error', 'หน้านี้สำหรับผู้ดูแลระบบ'); redirect('login.php'); }

$categories = ['men'=>'ผู้ชาย','women'=>'ผู้หญิง','kids'=>'เด็ก'];
$types = ['tops'=>'เสื้อ','shorts'=>'กางเกงขาสั้น','pants'=>'กางเกงขายาว','jeans'=>'กางเกงยีนส์','dresses'=>'เดรส','outerwear'=>'เสื้อคลุม','shoes'=>'รองเท้า','accessories'=>'แอ็กเซสซอรี่'];
$error = null;

if (($_GET['export'] ?? '') === 'products') {
    $rows = db()->query('SELECT id,name,category,product_type,brand,color,sizes,price,stock,is_active,created_at FROM products ORDER BY id DESC')->fetchAll();
    header('Content-Type: text/csv; charset=UTF-8'); header('Content-Disposition: attachment; filename="lunee-products-'.date('Y-m-d').'.csv"');
    echo "\xEF\xBB\xBF"; $out = fopen('php://output', 'wb'); fputcsv($out, ['ID','Name','Category','Type','Brand','Color','Sizes','Price','Stock','Active','Created']);
    foreach ($rows as $row) fputcsv($out, $row); fclose($out); exit;
}

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!verify_csrf($_POST['csrf'] ?? null)) {
        $error = 'เซสชันหมดอายุ กรุณาลองใหม่';
    } else {
        $action = $_POST['action'] ?? '';
        if ($action === 'delete') {
            $id = (int)($_POST['id'] ?? 0);
            if ($id > 0) db()->prepare('DELETE FROM products WHERE id=?')->execute([$id]);
            flash('success', 'ลบสินค้าออกจากร้านแล้ว'); redirect('admin.php');
        }
        if ($action === 'duplicate') {
            $id = (int)($_POST['id'] ?? 0); $s = db()->prepare('SELECT name,category,product_type,brand,color,sizes,price,stock,image_url,description,is_active FROM products WHERE id=?'); $s->execute([$id]); $source = $s->fetch();
            if ($source) { $source['name'] .= ' (สำเนา)'; db()->prepare('INSERT INTO products(name,category,product_type,brand,color,sizes,price,stock,image_url,description,is_active) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute(array_values($source)); flash('success', 'ทำสำเนาสินค้าแล้ว'); }
            redirect('admin.php');
        }
        if ($action === 'stock') {
            $id = (int)($_POST['id'] ?? 0); $stock = max(0, (int)($_POST['stock'] ?? 0)); db()->prepare('UPDATE products SET stock=? WHERE id=?')->execute([$stock,$id]); flash('success', 'อัปเดตสต็อกแล้ว'); redirect('admin.php');
        }
        if ($action === 'bulk') {
            $ids = array_values(array_filter(array_map('intval', (array)($_POST['ids'] ?? [])))); $mode = $_POST['bulk_mode'] ?? '';
            if ($ids) { $marks = implode(',', array_fill(0, count($ids), '?')); if ($mode === 'activate' || $mode === 'deactivate') db()->prepare("UPDATE products SET is_active=? WHERE id IN ($marks)")->execute(array_merge([$mode === 'activate' ? 1 : 0], $ids)); if ($mode === 'delete') db()->prepare("DELETE FROM products WHERE id IN ($marks)")->execute($ids); }
            flash('success', 'ดำเนินการกับสินค้าที่เลือกแล้ว'); redirect('admin.php');
        }
        if ($action === 'save') {
            $id = (int)($_POST['id'] ?? 0);
            $name = trim((string)($_POST['name'] ?? ''));
            $category = (string)($_POST['category'] ?? 'men');
            $type = (string)($_POST['product_type'] ?? 'tops');
            $brand = trim((string)($_POST['brand'] ?? ''));
            $color = trim((string)($_POST['color'] ?? ''));
            $sizes = trim((string)($_POST['sizes'] ?? 'S,M,L,XL,2XL'));
            $price = max(0, (float)($_POST['price'] ?? 0));
            $stock = max(0, (int)($_POST['stock'] ?? 0));
            $image = trim((string)($_POST['image_url'] ?? ''));
            $description = trim((string)($_POST['description'] ?? ''));
            $active = isset($_POST['is_active']) ? 1 : 0;
            if ($name === '' || $brand === '' || $color === '' || !isset($categories[$category]) || !isset($types[$type])) {
                $error = 'กรุณากรอกข้อมูลสินค้าให้ครบถ้วน';
            } elseif ($id > 0) {
                db()->prepare('UPDATE products SET name=?,category=?,product_type=?,brand=?,color=?,sizes=?,price=?,stock=?,image_url=?,description=?,is_active=? WHERE id=?')->execute([$name,$category,$type,$brand,$color,$sizes,$price,$stock,$image,$description,$active,$id]);
                flash('success', 'อัปเดตข้อมูลสินค้าแล้ว'); redirect('admin.php');
            } else {
                db()->prepare('INSERT INTO products(name,category,product_type,brand,color,sizes,price,stock,image_url,description,is_active) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$name,$category,$type,$brand,$color,$sizes,$price,$stock,$image,$description,$active]);
                flash('success', 'เพิ่มสินค้าใหม่เข้าร้านแล้ว'); redirect('admin.php');
            }
        }
    }
}

$edit = null;
if (isset($_GET['edit'])) { $s = db()->prepare('SELECT * FROM products WHERE id=?'); $s->execute([(int)$_GET['edit']]); $edit = $s->fetch() ?: null; }
$q = trim((string)($_GET['q'] ?? ''));
$filterCategory = (string)($_GET['category'] ?? '');
$filterStock = (string)($_GET['stock'] ?? '');
$where = [];
$params = [];
if ($q !== '') { $where[] = '(name LIKE ? OR brand LIKE ? OR color LIKE ?)'; $params = ["%$q%","%$q%","%$q%"]; }
if (isset($categories[$filterCategory])) { $where[] = 'category=?'; $params[] = $filterCategory; }
if ($filterStock === 'low') $where[] = 'stock BETWEEN 1 AND 5';
if ($filterStock === 'out') $where[] = 'stock=0';
$sql = 'SELECT * FROM products'.($where ? ' WHERE '.implode(' AND ', $where) : '').' ORDER BY id DESC';
$stmt = db()->prepare($sql); $stmt->execute($params); $products = $stmt->fetchAll();
$stats = [
    'products'=>(int)db()->query('SELECT COUNT(*) FROM products')->fetchColumn(),
    'active'=>(int)db()->query('SELECT COUNT(*) FROM products WHERE is_active=1')->fetchColumn(),
    'units'=>(int)db()->query('SELECT COALESCE(SUM(stock),0) FROM products')->fetchColumn(),
    'low'=>(int)db()->query('SELECT COUNT(*) FROM products WHERE stock BETWEEN 1 AND 5')->fetchColumn(),
    'members'=>(int)db()->query('SELECT COUNT(*) FROM users')->fetchColumn(),
    'orders'=>(int)db()->query('SELECT COUNT(*) FROM orders')->fetchColumn(),
    'revenue'=>(float)db()->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status <> 'cancelled'")->fetchColumn(),
    'pending'=>(int)db()->query("SELECT COUNT(*) FROM orders WHERE status IN ('pending','paid','packing')")->fetchColumn(),
];
$recentOrders = db()->query('SELECT o.order_number,o.total,o.status,o.created_at,u.name FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC LIMIT 5')->fetchAll();
$page_title = 'จัดการร้านค้า | '.STORE_NAME;
require __DIR__.'/partials_header.php';
?>
<main class="container admin-page">
  <section class="admin-tools" aria-label="เครื่องมือด่วน"><a class="admin-tool-card" href="admin.php?stock=low"><span class="tool-icon warning">!</span><span><b>เติมสต็อกสินค้า</b><small><?=$stats['low']?> รายการควรตรวจสอบ</small></span><strong>→</strong></a><a class="admin-tool-card" href="admin.php?export=products"><span class="tool-icon">↓</span><span><b>ส่งออกสินค้า CSV</b><small>ดาวน์โหลดรายการทั้งหมด</small></span><strong>→</strong></a><a class="admin-tool-card" href="admin_orders.php"><span class="tool-icon">↗</span><span><b>จัดการคำสั่งซื้อ</b><small><?=$stats['pending']?> รายการรอดำเนินการ</small></span><strong>→</strong></a><a class="admin-tool-card" href="index.php" target="_blank"><span class="tool-icon">⌂</span><span><b>ดูหน้าร้านจริง</b><small>เปิดในแท็บใหม่</small></span><strong>↗</strong></a></section>
  <?php if ($error): ?><div class="notice error" role="alert"><span>!</span><?=e($error)?><button aria-label="ปิดข้อความ">×</button></div><?php endif; ?>
  <section class="admin-hero panel"><div><div class="eyebrow">ADMIN CONTROL CENTER</div><h1>จัดการร้านค้า <span>✦</span></h1><p>ดูภาพรวมร้าน อัปเดตสินค้า และควบคุมสต็อกได้จากที่เดียว</p></div><div class="admin-hero-actions"><a class="button button-outline" href="admin_orders.php">ดูคำสั่งซื้อ <b>→</b></a><a class="button button-outline" href="admin.php?export=products">ส่งออก CSV <b>↓</b></a><a class="button" href="#product-form">เพิ่มสินค้า <b>＋</b></a></div></section>
  <section class="admin-stats" aria-label="ภาพรวมร้านค้า"><article class="admin-stat stat-products"><span class="admin-stat-icon">▦</span><div><small>สินค้าทั้งหมด</small><strong><?=$stats['products']?></strong><em><?=$stats['active']?> รายการกำลังแสดง</em></div></article><article class="admin-stat stat-stock"><span class="admin-stat-icon">◌</span><div><small>หน่วยในคลัง</small><strong><?=number_format($stats['units'])?></strong><em class="good">พร้อมขายวันนี้</em></div></article><article class="admin-stat stat-alert"><span class="admin-stat-icon">!</span><div><small>สินค้าใกล้หมด</small><strong><?=$stats['low']?></strong><em class="<?=$stats['low']?'warning':'good'?>"><?=$stats['low']?'ควรเติมสต็อก':'สต็อกปกติ'?></em></div></article><article class="admin-stat stat-orders"><span class="admin-stat-icon">↗</span><div><small>รอดำเนินการ</small><strong><?=$stats['pending']?></strong><em><?=$stats['orders']?> คำสั่งซื้อทั้งหมด</em></div></article><article class="admin-stat stat-revenue"><span class="admin-stat-icon">฿</span><div><small>ยอดขายรวม</small><strong>฿<?=number_format($stats['revenue'],0)?></strong><em class="good">ไม่รวมรายการยกเลิก</em></div></article></section>
  <section class="admin-workspace"><div class="panel admin-form-panel" id="product-form"><div class="panel-heading"><div><div class="eyebrow"><?=$edit?'EDIT PRODUCT':'NEW PRODUCT'?></div><h2><?=$edit?'แก้ไขสินค้า':'เพิ่มสินค้าใหม่'?></h2></div><?php if($edit): ?><a class="text-button" href="admin.php">ยกเลิก</a><?php endif; ?></div><form method="post" class="admin-form" id="admin-product-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="field"><label for="name">ชื่อสินค้า</label><input id="name" name="name" value="<?=e($edit['name']??'')?>" placeholder="เช่น Everyday Linen Shirt" required></div><div class="field"><label for="brand">แบรนด์</label><input id="brand" name="brand" value="<?=e($edit['brand']??'')?>" placeholder="เช่น LUNEÉ" required></div><div class="field"><label for="category">หมวดหมู่</label><select id="category" name="category"><?php foreach($categories as $v=>$label): ?><option value="<?=$v?>" <?=($edit['category']??'men')===$v?'selected':''?>><?=$label?></option><?php endforeach; ?></select></div><div class="field"><label for="product_type">ประเภทสินค้า</label><select id="product_type" name="product_type"><?php foreach($types as $v=>$label): ?><option value="<?=$v?>" <?=($edit['product_type']??'tops')===$v?'selected':''?>><?=$label?></option><?php endforeach; ?></select></div><div class="field"><label for="color">สี</label><input id="color" name="color" value="<?=e($edit['color']??'')?>" placeholder="เช่น เขียวมะกอก" required></div><div class="field"><label for="sizes">ไซซ์ <small>S, M, L, XL, 2XL</small></label><input id="sizes" name="sizes" value="<?=e($edit['sizes']??'S,M,L,XL,2XL')?>" required></div><div class="field"><label for="price">ราคา (บาท)</label><input id="price" name="price" type="number" min="0" step="0.01" value="<?=e($edit['price']??'')?>" placeholder="0.00" required></div><div class="field"><label for="stock">สต็อก</label><input id="stock" name="stock" type="number" min="0" value="<?=e($edit['stock']??0)?>" required></div><div class="field full-field"><label for="image_url">ลิงก์รูปภาพ <small>วาง URL รูปจากภายนอกได้</small></label><input id="image_url" name="image_url" value="<?=e($edit['image_url']??'')?>" placeholder="https://..."><div class="image-preview" id="image-preview"><span>พรีวิวรูปภาพจะแสดงที่นี่</span></div></div><div class="field full-field"><label for="description">รายละเอียดสินค้า</label><textarea id="description" name="description" rows="4" placeholder="เล่าเรื่องสินค้าแบบสั้น ๆ"><?=e($edit['description']??'')?></textarea></div><label class="admin-toggle"><input type="checkbox" name="is_active" value="1" <?=(!isset($edit)||($edit['is_active']??0))?'checked':''?>><span class="toggle-ui"></span><span>แสดงสินค้านี้บนหน้าร้าน</span></label><button class="button full save-product" type="submit"><span><?=$edit?'บันทึกการแก้ไข':'เพิ่มสินค้าเข้าร้าน'?></span><b>→</b></button></form></div>
    <div class="panel inventory-panel"><div class="panel-heading"><div><div class="eyebrow">INVENTORY</div><h2>คลังสินค้า</h2></div><span class="inventory-count"><?=count($products)?> รายการ</span></div><form class="inventory-toolbar" method="get"><div class="inventory-search"><span>⌕</span><input name="q" value="<?=e($q)?>" placeholder="ค้นหาชื่อ แบรนด์ หรือสี..."></div><select name="category"><option value="">ทุกหมวดหมู่</option><?php foreach($categories as $v=>$label): ?><option value="<?=$v?>" <?=$filterCategory===$v?'selected':''?>><?=$label?></option><?php endforeach; ?></select><select name="stock"><option value="">ทุกสต็อก</option><option value="low" <?=$filterStock==='low'?'selected':''?>>ใกล้หมด (1–5)</option><option value="out" <?=$filterStock==='out'?'selected':''?>>หมดสต็อก</option></select><button class="button button-small" type="submit">ค้นหา</button><?php if($q||$filterCategory||$filterStock): ?><a class="text-button" href="admin.php">ล้างตัวกรอง</a><?php endif; ?></form><div class="inventory-list"><?php foreach($products as $p): ?><article class="inventory-item"><div class="inventory-thumb"><img src="<?=e($p['image_url'])?>" alt="<?=e($p['name'])?>" loading="lazy"></div><div class="inventory-info"><div class="inventory-top"><span class="product-chip"><?=e($types[$p['product_type']??'tops']??'สินค้า')?></span><span class="stock-badge <?=$p['stock']<1?'out':($p['stock']<=5?'low':'ready')?>"><?=$p['stock']<1?'หมดสต็อก':($p['stock']<=5?'เหลือ '.$p['stock']:'พร้อมขาย')?></span></div><h3><?=e($p['name'])?></h3><p><?=e($p['brand'])?> · <?=e($p['color'])?></p><strong>฿<?=number_format((float)$p['price'],2)?></strong></div><div class="inventory-actions"><a class="icon-action" href="admin.php?edit=<?=$p['id']?>" title="แก้ไข">✎</a><form method="post" onsubmit="return confirm('ลบสินค้านี้ใช่หรือไม่?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="icon-action danger-icon" title="ลบ" type="submit">×</button></form></div></article><?php endforeach; ?><?php if(!$products): ?><div class="empty-inventory"><span>⌕</span><h3>ไม่พบสินค้าที่ค้นหา</h3><p>ลองเปลี่ยนคำค้นหาหรือล้างตัวกรอง</p></div><?php endif; ?></div></div></section>
  <section class="panel recent-orders"><div class="panel-heading"><div><div class="eyebrow">RECENT ACTIVITY</div><h2>คำสั่งซื้อล่าสุด</h2></div><a class="text-button" href="admin_orders.php">ดูทั้งหมด →</a></div><?php if($recentOrders): ?><div class="recent-order-list"><?php foreach($recentOrders as $order): ?><a class="recent-order" href="admin_orders.php"><span class="order-avatar"><?=e(mb_strtoupper(mb_substr($order['name'],0,1)))?></span><span><b>#<?=e($order['order_number'])?></b><small><?=e($order['name'])?> · <?=e(date('d/m H:i',strtotime($order['created_at'])))?></small></span><strong>฿<?=number_format((float)$order['total'],2)?></strong><em class="order-pill status-<?=e($order['status'])?>"><?=e(['pending'=>'รอดำเนินการ','paid'=>'ชำระแล้ว','packing'=>'กำลังแพ็ก','shipped'=>'จัดส่งแล้ว','completed'=>'สำเร็จ','cancelled'=>'ยกเลิก'][$order['status']]??$order['status'])?></em></a><?php endforeach; ?></div><?php else: ?><div class="empty-activity"><span>✦</span><p>ยังไม่มีคำสั่งซื้อใหม่</p></div><?php endif; ?></section>
</main>
<style>
.admin-page{padding:34px 24px 80px}.admin-hero{display:flex;justify-content:space-between;align-items:flex-end;margin:0 0 18px;padding:30px 32px;background:linear-gradient(120deg,#e5efe7,#f7faf6 72%);border-color:#d5e3d8}.admin-hero h1{font-size:38px;margin:6px 0}.admin-hero h1 span{color:#d5a73d;font-size:23px}.admin-hero p{color:var(--muted);margin:0}.admin-hero-actions{display:flex;gap:10px}.admin-hero-actions .button{gap:16px}.admin-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:18px 0 22px}.admin-stat{display:flex;gap:14px;align-items:flex-start;padding:20px;background:#fff;border:1px solid var(--line);border-radius:12px;box-shadow:0 8px 20px rgba(41,57,45,.04)}.admin-stat-icon{display:grid;place-items:center;width:40px;height:40px;border-radius:12px;background:#edf4ee;color:var(--accent);font-size:20px}.stat-alert .admin-stat-icon{background:#fff4dd;color:#b47700}.admin-stat small,.admin-stat em{display:block;color:var(--muted);font-style:normal;font-size:12px}.admin-stat strong{display:block;font-size:27px;margin:2px 0}.admin-stat em.good{color:#438052}.admin-stat em.warning{color:#bd7710}.admin-workspace{display:grid;grid-template-columns:minmax(330px,.8fr) minmax(500px,1.2fr);gap:20px;align-items:start}.admin-workspace .panel{margin:0;padding:26px}.panel-heading{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:20px}.panel-heading h2{margin:5px 0 0;font-size:23px}.text-button{border:0;background:transparent;color:var(--accent);font-weight:700;cursor:pointer}.admin-form{display:grid;grid-template-columns:1fr 1fr;gap:14px}.admin-form .field{margin:0}.admin-form .field small{color:var(--muted);font-weight:400}.full-field{grid-column:1/-1}.admin-form textarea{resize:vertical}.image-preview{height:130px;margin-top:9px;border:1px dashed #c9d8cc;border-radius:10px;background:#f5f8f4;display:grid;place-items:center;overflow:hidden;color:var(--muted);font-size:12px}.image-preview img{width:100%;height:100%;object-fit:cover}.admin-toggle{grid-column:1/-1;display:flex;align-items:center;gap:9px;font-size:13px;color:var(--muted);cursor:pointer}.admin-toggle input{display:none}.toggle-ui{width:38px;height:22px;border-radius:20px;background:#d5ddd6;position:relative;transition:.2s}.toggle-ui:after{content:'';position:absolute;left:3px;top:3px;width:16px;height:16px;background:#fff;border-radius:50%;transition:.2s;box-shadow:0 1px 3px #999}.admin-toggle input:checked+.toggle-ui{background:var(--accent)}.admin-toggle input:checked+.toggle-ui:after{transform:translateX(16px)}.save-product{grid-column:1/-1;margin-top:2px}.inventory-count{font-size:12px;color:var(--muted);padding-top:6px}.inventory-toolbar{display:grid;grid-template-columns:minmax(150px,1fr) 125px 125px auto;gap:8px;align-items:center;margin-bottom:14px}.inventory-search{display:flex;align-items:center;border:1px solid #d9dcd8;border-radius:7px;padding:0 9px}.inventory-search span{font-size:20px;color:var(--muted)}.inventory-search input{border:0;padding:10px 6px}.inventory-search input:focus{box-shadow:none}.inventory-toolbar select{padding:10px 8px}.inventory-toolbar .text-button{font-size:12px;white-space:nowrap}.inventory-list{display:grid;gap:9px}.inventory-item{display:grid;grid-template-columns:60px 1fr auto;gap:12px;align-items:center;padding:10px;border:1px solid #edf0eb;border-radius:10px;transition:.2s}.inventory-item:hover{border-color:#c4d8c8;box-shadow:0 6px 16px rgba(35,67,44,.07);transform:translateY(-1px)}.inventory-thumb{width:60px;height:68px;border-radius:7px;overflow:hidden;background:#eef2ee}.inventory-thumb img{width:100%;height:100%;object-fit:cover}.inventory-top{display:flex;gap:6px;align-items:center}.product-chip,.stock-badge{display:inline-block;font-size:10px;padding:4px 7px;border-radius:99px;background:#eef4ef;color:var(--accent)}.stock-badge{background:#e6f3e8;color:#3c8050}.stock-badge.low{background:#fff3da;color:#a66a00}.stock-badge.out{background:#fbe8e8;color:#a74343}.inventory-info h3{font-size:14px;margin:6px 0 2px}.inventory-info p{margin:0 0 4px;font-size:11px;color:var(--muted)}.inventory-info strong{font-size:13px}.inventory-actions{display:flex;gap:6px;align-items:center}.inventory-actions form{margin:0}.icon-action{display:grid;place-items:center;width:30px;height:30px;border:1px solid #dbe5dd;border-radius:7px;background:#fff;color:var(--accent);cursor:pointer;font-size:16px}.icon-action:hover{background:#edf5ee}.danger-icon{color:#a74343;border-color:#eed5d5}.empty-inventory{text-align:center;padding:42px 10px;color:var(--muted)}.empty-inventory span{font-size:30px}.empty-inventory h3{color:var(--ink);margin:8px 0 4px}.empty-inventory p{margin:0;font-size:13px}@media(max-width:1050px){.admin-stats{grid-template-columns:repeat(2,1fr)}.admin-workspace{grid-template-columns:1fr}.inventory-panel{order:2}}@media(max-width:650px){.admin-page{padding:20px 14px 60px}.admin-hero{display:block;padding:23px}.admin-hero h1{font-size:30px}.admin-hero-actions{margin-top:20px}.admin-stats{grid-template-columns:1fr}.admin-workspace .panel{padding:19px}.admin-form{grid-template-columns:1fr}.full-field,.save-product,.admin-toggle{grid-column:auto}.inventory-toolbar{grid-template-columns:1fr 1fr}.inventory-search{grid-column:1/-1}.inventory-toolbar .button{width:100%}.inventory-item{grid-template-columns:48px 1fr auto}.inventory-thumb{width:48px;height:58px}.inventory-actions{flex-direction:column}}
