<style>
.admin-tools{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:0 0 20px}.admin-tool-card{display:flex;align-items:center;gap:10px;padding:14px 15px;background:#fff;border:1px solid var(--line);border-radius:11px;transition:.2s}.admin-tool-card:hover{border-color:#b9d0bd;box-shadow:0 8px 18px rgba(35,67,44,.08);transform:translateY(-2px)}.admin-tool-card .tool-icon{display:grid;place-items:center;flex:0 0 34px;width:34px;height:34px;border-radius:10px;background:#edf4ee;color:var(--accent);font-weight:700}.admin-tool-card .tool-icon.warning{background:#fff3da;color:#a66a00}.admin-tool-card b{display:block;font-size:12px}.admin-tool-card small{display:block;margin-top:3px;color:var(--muted);font-size:10px}.admin-tool-card strong{margin-left:auto;color:var(--accent)}.bulk-toolbar{display:flex;align-items:center;gap:10px;margin:0 0 12px;padding:10px 12px;border:1px solid #dce8de;border-radius:9px;background:#f7fbf7}.bulk-toolbar div{margin-right:auto}.bulk-toolbar b,.bulk-toolbar small{display:block}.bulk-toolbar b{font-size:11px}.bulk-toolbar small{color:var(--muted);font-size:10px;margin-top:2px}.bulk-toolbar select{width:auto;padding:8px 9px;font-size:11px}.product-check{display:grid;place-items:center;width:18px;height:18px;cursor:pointer}.product-check input{position:absolute;opacity:0;pointer-events:none}.product-check span{display:block;width:17px;height:17px;border:1px solid #c8d6cb;border-radius:5px;background:#fff;transition:.18s}.product-check input:checked+span{background:var(--accent);border-color:var(--accent);box-shadow:inset 0 0 0 3px #fff}.inventory-item:has(.product-check){grid-template-columns:20px 60px 1fr auto}.recent-orders{margin-top:20px}.recent-order-list{display:grid;gap:2px}.recent-order{display:grid;grid-template-columns:35px 1fr auto auto;align-items:center;gap:12px;padding:12px 5px;border-top:1px solid #edf0eb}.recent-order:hover{background:#f7faf7}.order-avatar{display:grid;place-items:center;width:32px;height:32px;border-radius:50%;background:#e3eee5;color:var(--accent);font-size:12px;font-weight:700}.recent-order b{display:block;font-size:12px}.recent-order small{display:block;color:var(--muted);font-size:10px;margin-top:3px}.recent-order strong{font-size:12px}.order-pill{font-style:normal;font-size:10px;padding:5px 8px;border-radius:99px;background:#e8f3e9;color:#3c8050}.status-cancelled{background:#fbe8e8;color:#a74343}.status-pending,.status-paid{background:#fff3da;color:#a66a00}.empty-activity{text-align:center;padding:22px;color:var(--muted)}.empty-activity span{font-size:24px;color:#c6d9c8}.empty-activity p{margin:6px 0;font-size:12px}@media(max-width:1050px){.admin-tools{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){.admin-tools{grid-template-columns:1fr}.bulk-toolbar{align-items:stretch;flex-wrap:wrap}.bulk-toolbar div{width:100%}.bulk-toolbar select,.bulk-toolbar button{flex:1}.recent-order{grid-template-columns:32px 1fr auto}.recent-order .order-pill{grid-column:2/4;justify-self:start}.recent-order strong{grid-column:3;grid-row:1}.inventory-item:has(.product-check){grid-template-columns:18px 48px 1fr auto}.inventory-item .product-check{grid-row:1;grid-column:1}}
