<script>(()=>{const input=document.querySelector('#image_url'),preview=document.querySelector('#image-preview');if(!input||!preview)return;const render=()=>{const url=input.value.trim();preview.innerHTML='';if(!url){preview.innerHTML='<span>พรีวิวรูปภาพจะแสดงที่นี่</span>';return}const img=new Image();img.alt='พรีวิวสินค้า';img.onload=()=>preview.appendChild(img);img.onerror=()=>preview.innerHTML='<span>ลิงก์รูปภาพไม่ถูกต้อง</span>';img.src=url};input.addEventListener('input',render);render()})();</script>
<script>(()=>{const list=document.querySelector('.inventory-list');if(!list)return;const token=document.querySelector('input[name="csrf"]')?.value||'';const items=[...list.querySelectorAll('.inventory-item')];if(!items.length)return;const bar=document.createElement('form');bar.method='post';bar.className='bulk-toolbar';bar.innerHTML='<input type="hidden" name="csrf" value="'+token+'"><input type="hidden" name="action" value="bulk"><div><b>เครื่องมือหลายรายการ</b><small>เลือกสินค้าแล้วใช้คำสั่งพร้อมกัน</small></div><select name="bulk_mode"><option value="activate">เปิดแสดงสินค้า</option><option value="deactivate">ซ่อนสินค้า</option><option value="delete">ลบที่เลือก</option></select><button class="button button-small" type="submit">ใช้กับที่เลือก</button>';list.parentElement.insertBefore(bar,list);items.forEach(item=>{const id=item.querySelector('input[name="id"]')?.value||new URL(item.querySelector('a[href*="edit="]')?.href||location.href).searchParams.get('edit');if(!id)return;const check=document.createElement('label');check.className='product-check';check.innerHTML='<input type="checkbox" data-product-id="'+id+'"><span></span>';item.prepend(check);});bar.addEventListener('submit',event=>{const selected=items.map(item=>item.querySelector('[data-product-id]')).filter(input=>input?.checked).map(input=>'<input type="hidden" name="ids[]" value="'+input.dataset.productId+'">').join('');if(!selected){event.preventDefault();alert('กรุณาเลือกสินค้าอย่างน้อย 1 รายการ');return}bar.insertAdjacentHTML('beforeend',selected);if(bar.querySelector('[name="bulk_mode"]').value==='delete'&&!confirm('ลบสินค้าที่เลือกใช่หรือไม่?'))event.preventDefault();});})();</script>
